"""A surface cue for predicate-like words: inflected verb endings in several
scripts, plus common copulas and modal forms. It does not try to translate text."""
READS = ()

LATIN_ENDINGS = (
    "ing", "ed", "ait", "ent", "ons", "ez", "ant", "é", "ée", "és",
    "ando", "iendo", "aron", "ieron", "aba", "ía", "ió", "ó", "ano",
    "et", "end", "iert", "ło", "ły", "li", "ał", "ł", "ają", "uje",
    "iam", "irent", "issent", "rait", "arent", "iesz",
)
SLAVIC_ENDINGS = (
    "ать", "ять", "ить", "еть", "уть", "ться", "тись", "ется",
    "аются", "ают", "уют", "или", "ала", "ало", "али", "ели", "яли",
    "ает", "ет", "ит", "ют", "ят", "ешь", "ывать", "ивать", "ывают",
    "л", "ли", "гут", "ёт", "ат", "ут", "ем", "ны",
)
JAPANESE_ENDINGS = (
    "する", "した", "して", "ます", "ました", "れる", "られる", "いる",
    "える", "める", "なる", "った", "って", "んで", "です", "になります",
    "となる", "ている", "できる", "わない", "えた",
)

# Common irregular predicates and modal forms that do not have a useful suffix.
LATIN_PREDICATES = frozenset(("sind", "ist", "wird", "werden", "hält"))
SLAVIC_PREDICATES = frozenset(("есть", "могут", "нельзя", "возможно", "можно"))


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if not word:
        return None, 0.0

    if any("\u0400" <= ch <= "\u052f" for ch in word):
        fires = word in SLAVIC_PREDICATES or word.endswith(SLAVIC_ENDINGS)
    elif any("\u3040" <= ch <= "\u30ff" for ch in word):
        fires = word.endswith(JAPANESE_ENDINGS)
    elif any("\u3400" <= ch <= "\u9fff" for ch in word):
        fires = word.endswith("了")
    elif any("\u0600" <= ch <= "\u06ff" for ch in word):
        fires = word.endswith("ت")
    elif any("a" <= ch <= "z" or ch in "àáâäãåæçèéêëìíîïñòóôöõøùúûüýÿ" for ch in word):
        fires = word in LATIN_PREDICATES or word.endswith(LATIN_ENDINGS)
    else:
        fires = False

    return None, 0.0045 + (0.11 if fires else 0.0)

programs.haiku:
"""layers.0.mlp.down_proj:4609 -- a sparse "test-directory / try-again" detector.

Almost always near zero. It fires NEGATIVELY on a few recognisable spots:

1. The path segment right after a "test" directory name, when the word "test"
   or "tests" is glued to it: the "bed" of "/testbed", the "/java" of
   "src/test/java", the "/unit" of "tests/unit" (strongest on "bed").
2. The word that completes "try again", "try and", "help but" (as in
   "can't help but feel"), and "check if" / "sure if".
3. The Chinese character after 试 / 試 (try / trial / test, as in 试驾, 试读).

It fires slightly POSITIVELY on "log" in "console.log".

The program reads only the last two tokens of the prefix and carries no state
across positions. A row's first token, and any token whose predecessor is in
another document, gets 0.
"""

READS = ()

# Words that, as a glued-on fragment, name a "test" directory or identifier.
TEST_WORDS = {"test", "tests", "/test", "/tests", "_test", "-test"}
TRY_WORDS = {"try", "Try"}
HELP_WORDS = {"help"}
CHECK_WORDS = {"check", "Check", "sure", "unsure"}
TRY_CHARS = {"试", "試"}


def step(carry, prefix, upstream):
    if len(prefix) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    prev = prefix.token_strings[-2]
    cur = prefix.token_strings[-1]
    word = cur.strip()
    value = 0.0
    if prev in TEST_WORDS:
        if word == "bed":
            value = -0.55
        elif cur.startswith("/") and len(cur) > 1:
            value = -0.4
    elif prev.strip() in TRY_WORDS and word in {"again", "and"}:
        value = -1.0
    elif prev.strip() in HELP_WORDS and word == "but":
        value = -1.2
    elif prev.strip() in CHECK_WORDS and word == "if":
        value = -0.35
    elif prev in TRY_CHARS:
        value = -0.3
    elif prev.strip() == "console" and cur == ".log":
        value = 0.17
    return carry, float(value)

programs.sol:
"""Approximate the component's large, sparse text-opening responses.

Opening Python f-strings, assigned multiline literals and backtick templates
produce negative pulses. File read/write and selected regex operations also
produce negative pulses. Familiar web labels and a document-initial Q: header
have separate fixed responses. The amplitudes approximate training-data averages.
A 60-character tail is reset at document boundaries. The small background
is constant; this deliberately omits most token-specific lexical variation.
"""
import re

READS = ()
# Recognize a Python f prefix in an expression, not the quoted letter f.
FORMAT_PREFIX = re.compile(
    r'(?:^|[=(,:+]\s*|\b(?:return|yield)\s+)f$'
)
RAW_PREFIX = re.compile(r'(?:^|[^\w])[rR]$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    stripped = token.lstrip()
    value = -0.0013
    if re.search(r'(?:^|[\s(=,:])f$', tail) and token in ('.read', '.write'):
        value = -0.35
    if re.search(r'(?:^|[^\w])re$', tail) and token in ('.compile', '.findall'):
        value = -0.55
    if FORMAT_PREFIX.search(tail):
        if token.startswith("'") and not token.startswith(("')", "',", "']", "'}")):
            value = -0.90
        elif token.startswith('"'):
            value = -0.82 if len(token) == 1 else -0.68
        elif token.startswith(('\\"', "\\'")):
            value = -0.52
    elif RAW_PREFIX.search(tail):
        if token.startswith(("'^", "'\\", '"^', '"\\')):
            value = -0.70
    # Literal or special-form openings on an assignment's right-hand side.
    if tail.rstrip().endswith('='):
        if stripped.startswith(("'''", '"""')):
            value = -1.15
        elif stripped.startswith('`'):
            value = -0.90 if '\n' in token else -0.35
        elif stripped.startswith('@"'):
            value = -0.56
        elif stripped in ('"', "'"):
            value = -0.12
        elif stripped in ('require', 'await', 'function'):
            value = -0.25
    if stripped.startswith(('("""', "('''")):
        value = -1.10
    if stripped.startswith(('"""', "'''")) and tail.rstrip().endswith('return'):
        value = -1.10
    if (tail.endswith(('=""', "('")) and
            token.startswith(('"\n', "''\n"))):
        value = -1.0
    # Distinct textual interface/header cues, not general word predictions.
    if token in (' Tags', 'Tags') and re.search(r'\b(?:Show|Hide)$', tail):
        value = 0.52
    if token == ' More' and re.search(r'\bRead$', tail):
        value = 0.46
    if token == ' Profile' and tail == 'Community':
        value = -0.246
    if token == ':\n\n' and tail == 'Q':
        value = 0.264
    return (doc, (tail + token)[-60:]), float(value)

"""Approximate a written-numeral-1 detector, with a short numeric echo.

Leading 1s are strong; internal 1s are weaker, especially after another 1.
The digit following a 1 has a digit-dependent response.  Document-initial
numerals are stronger; later 1s decline gently with document position.
Chinese 一, single-character numeric ones, end-of-text markers, carriage
returns, and a few lexical classes have separate responses.  Everything
else stays near zero.  This is surface-text logic, not a semantic parser.
"""
import math
import unicodedata

READS = ()
TEENS = frozenset((
    'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen',
    'sixteen', 'seventeen', 'eighteen', 'nineteen',
))
TENS = frozenset((
    'twenty', 'thirty', 'forty', 'fifty',
    'sixty', 'seventy', 'eighty', 'ninety',
))


def leading_one(previous):
    """Differentiate decimal digits, identifier suffixes and separated numbers."""
    if previous in '0123456789' and len(previous) == 1:
        return 0.39 if previous == '1' else 1.05
    if previous.endswith('_'):
        return 1.83
    if previous.endswith('\n'):
        return 1.56
    if previous.isspace():
        return 1.48
    if previous.endswith('.'):
        return 1.21
    if previous.endswith(('(', '[', '{', '/', '\\')):
        return 1.65
    if previous.endswith(('-', '+', '=', ':')):
        return 1.36
    if previous.endswith(','):
        return 1.40
    if previous.endswith(('"', "'")):
        return 1.81
    if previous and previous[-1].isalpha():
        return 1.70
    return 1.50


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        previous, position = carry[1], carry[2] + 1
    token = prefix.token_strings[-1]
    word = token.strip().strip('=():_-.').lower()
    value = 0.005
    if token == '<|endoftext|>':
        value = 2.10
    elif token == '1':
        if position == 0:
            value = 4.06
        else:
            value = leading_one(previous) + 0.24 - 0.047 * math.log1p(position)
    elif len(token) == 1 and token in '023456789':
        if position == 0:
            value = 0.55 if token in '03' else 0.78
        elif previous == '1':
            digit = int(token)
            if digit in (0, 2):
                value = -0.07
            elif digit == 3:
                value = 0.20
            else:
                value = min(0.74, 0.12 * digit - 0.02)
        else:
            value = -0.07 if token == '9' else 0.005
    elif '一' in token:
        if token == '一':
            value = 1.45
        else:
            value = 1.12 if token.startswith('一') else 0.68
    elif len(token) == 1 and unicodedata.numeric(token, -1) == 1:
        value = 1.44
    elif token == '\r':
        value = 0.96
    elif word == 'true':
        value = 0.83
    elif word == 'false':
        value = 0.18
    elif word in ('null', 'zero'):
        value = -0.18
    elif word == 'white' or token == '白':
        value = 0.84
    elif word in ('january', 'monday'):
        value = 0.95
    elif word in ('jan', 'november'):
        value = 0.62
    elif word in TEENS:
        value = 0.85
    elif word in TENS or word == 'hundred':
        value = 0.45
    return (doc, token, position), float(value)

