"""Draft 2: the digit one (in any script) and digits that follow a one."""
READS = ()

ONE_SIGNS = set("1１¹₁一")
DIGITS = set("0123456789")
END = "<|endoftext|>"

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if prefix.position > 0 else ""
    if tok == END:
        return None, 2.1
    if tok in ONE_SIGNS:
        if prev in ONE_SIGNS:
            return None, 0.4
