programs.sol:
"""Lexical click detector, with weaker get and interface-control responses.

This responds to words and code identifiers, not actual mouse use. Click
inflections, translations and fragments have different strengths; 'get' and
UI controls are weaker. A click instruction's next word, or a split suffix,
can respond too. Other tokens get zero. State resets at document boundaries.
"""
READS = ()

CLICK = {
    'clicks': 6.5, 'clicking': 6.2, 'clicked': 5.6, 'clickable': 3.3,
    'klik': 3.2, 'clic': 2.1, 'クリック': 3.6, '点击': 6.1,
}
CONTROLS = {
    'button': 1.1, 'buttons': 1.1, 'btn': 0.9, 'checkbox': 1.0,
    'tap': 1.1, 'taps': 0.9, 'tapping': 1.1, 'tapped': 0.4,
    'press': 0.4, 'pressed': 0.35, 'pressing': 0.5,
    'mouse': 0.6, 'scroll': 1.0, 'scrolling': 0.8, 'hover': 1.1,
    'toggle': 0.65, 'flick': 1.4,
    '按钮': 1.0, '按键': 0.9, '按': 0.7, '按下': 0.8,
    '拍': 0.95, '点': 0.4, '點': 0.65, '击': 1.9, '擊': 1.4,
    'кноп': 1.4,
}
FOLLOWING = {
    ' the': 2.6, ' on': 1.16, ' to': 1.8, ' of': 3.1,
    ' here': 0.56, ' Here': 0.44, ' it': 0.85, ' a': 0.8,
    'ing': 4.35, 's': 3.8, 'ed': 3.4, 'er': 2.0,
    'ers': 1.55, 'able': 1.2,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    following = carry is not None and carry[0] == doc and carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('._/-(\'"#=<')
    lower = word.lower()
    value = 0.0
    if lower == 'click':
        value = 7.2 if token == ' click' else 8.0
        if token[:1] in ('_', '-', '(') or word.isupper() or token == '.Click':
            value = 6.5
    elif lower in CLICK:
        value = CLICK[lower]
        if lower == 'clicked' and not token.startswith(' '):
            value = 4.5 if token[0].isalpha() else 3.6
    elif 'click' in lower:
        value = 2.5 if 'listener' in lower else 3.8
    elif lower in ('cli', 'lick'):
        value = 0.8 if lower == 'cli' else 2.55
    elif lower in ('get', 'gets', 'getting'):
        value = {'get': 0.9, 'gets': 0.55, 'getting': 0.64}[lower]
    elif word[:3].lower() == 'get' and len(word) > 3 and word[3].isupper():
        value = max(0.1, 1.15 - 0.045 * len(word))
    elif lower in CONTROLS:
        value = CONTROLS[lower]
    elif lower in ('jbutton', 'imagebutton', 'uibutton', 'mouseevent',
                   'mouseover', 'mousedown', 'mouseup', 'keydown', 'keypress'):
        value = 1.2
    if following and token in FOLLOWING:
        value = FOLLOWING[token]
    return (doc, lower == 'click' or lower in CLICK), float(value)

