"""Predict large responses to click/klik actions and smaller ones to get/getter words."""
READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    low = raw.casefold()
    if "onclick" in low or "on-click" in low:
        return None, 4.0
    if "click" in low:
        return None, 6.8
    if "klik" in low:
        return None, 3.5
    core = raw.lstrip("._/$")
    folded = core.casefold()
    if folded in {"get", "gets", "getting", "gotten"}:
        return None, 0.9
    if folded.startswith("get"):
        rest = core[3:]
        if rest and (rest[0].isupper() or not rest[0].isalpha()):
            return None, 0.9
    return None, 0.0

programs.haiku:
"""Candidate 4: verbs meaning 'to do' or 'to make', in English and other languages.

The component is strongly negative on these verbs. Chinese 做 ('to do / make') is the
strongest, about -6.5 alone and about -3.5 inside compounds such as 做好 or 做了. English
do/does/did/doing/done sit near -1; make/made/making near -0.5. Other languages' do/make
verbs (làm, ทำ, сделать, делать, hacer, faire, 制作, 作り) fall between. Everything else is 0.
"""
READS = ()

ZUO = "做"                      # Chinese 'do / make'
DO_EN = {"do": -1.2, "does": -1.1, "did": -1.0, "doing": -1.5, "done": -0.8}
MAKE_EN = {"make": -0.5, "makes": -0.3, "made": -0.7, "making": -0.5}
OTHER = {
    "làm": -2.5, "ทำ": -3.0, "作": -2.0,               # Vietnamese, Thai, Chinese/Japanese 'make'
    "сделать": -1.4, "сделал": -1.3, "делать": -1.3,   # Russian
    "hacer": -0.9, "faire": -0.4, "wykon": -0.8, "制作": -1.4, "作り": -1.2,
}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if ZUO in tok:
        return None, -6.5 if tok == ZUO else -3.5
    word = tok.strip().lower()
    for table in (DO_EN, MAKE_EN, OTHER):
        if word in table:
            return None, table[word]
    return None, 0.0

