programs.sol:
"""Approximate an 'of' token detector using two tokens of left context.

Counting, classifying, collection and institution words weaken the response;
quantifiers strengthen it. Articles, a final 's', and capitalization make small
adjustments. Spelling variants have lower fixed responses. At document starts
there is no left context. Other common prepositions get 0.03, other tokens zero.

These lexical classes approximate strength, not a full grammatical parse;
word-specific differences within a class and small background responses remain.
"""
READS = ()

COUNT_OR_COLLECTION = frozenset(
    'number numbers amount amounts sum sums set sets list lists group groups '
    'collection collections pair pairs couple couples'.split())
TYPE_OR_INSTANCE = frozenset(
    'type types kind kinds sort sorts instance instances'.split())
INSTITUTION = frozenset(
    'university universities department departments institute institutes '
    'college colleges ministry ministries bureau office faculty school council board'.split())
QUANTIFIERS = frozenset('all some each many much both few several those'.split())
PREPOSITIONS = frozenset('to in for on by with from about among into at'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, penultimate = '', ''
    else:
        _, previous, penultimate = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.03 if word in PREPOSITIONS else 0.0
    if word.lstrip('-_.') == 'of':
        value = 1.12
        if token == ' of':
            head = previous.strip().lower()
            article = penultimate.strip().lower()
            value = 1.62
            if head in COUNT_OR_COLLECTION:
                value -= 0.71
            elif head in TYPE_OR_INSTANCE or head in ('lot', 'lots'):
                value -= 1.08
            elif head in INSTITUTION:
                value -= 0.75
            elif head in ('example', 'examples'):
                value -= 0.47
            elif head in QUANTIFIERS:
                value += 0.21
            elif head in ('out', 'instead'):
                value -= 0.45
            elif head == '%':
                value -= 0.81
            if article == 'the':
                value -= 0.26
            elif article in ('a', 'an'):
                value -= 0.23
            if head.endswith('s'):
                value += 0.10
            if previous[:1].isspace() and previous.strip()[:1].isupper():
                value -= 0.17
            if not previous:
                value = 1.66
        elif word[:1] == '.':
            value = 0.82
        elif token == 'of':
            value = 0.85
        elif token == 'Of':
            value = 1.06
    return (doc, token, previous), float(value)

"""Predict a spelling-sensitive response centered on y.

