READS = ()
ZERO = {'0', '０'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, before_previous, run, only_zeros = '', '', 0, True
        first = True
    else:
        _, previous, before_previous, run, only_zeros = carry
        first = False

    value = 0.0
    if s in ZERO:
        run = run + 1 if previous in ZERO else 1
        if only_zeros:
            value = 6.16
        elif run >= 2:
            value = 1.60 + (0.30 if run >= 3 else 0.0)
            value += 0.05 * min(max(run - 3, 0), 5)
        else:
            value = -0.02
            if previous == '5':
                value = 0.20  # The numeric ending 50.
            if before_previous in ZERO:
                value += 0.23
                if previous == '.':
                    value = 0.68
                elif previous == ',':
                    value = 0.55
                elif previous.isspace():
                    value = 0.60
                elif previous == '-':
                    value = 0.41
