        value = 5.9 if word == '白色' else 4.7
    elif word in ('白白', '黑白'):
        value = 6.3 if word == '白白' else 4.2
    elif word.startswith('蛋白') or word == '面白い':
        value = 0.2
    elif '白' in word:
        value = 2.0
    elif word in COLOURS:
        value = COLOURS[word]
        if word in ('black', 'yellow') and capital:
            value += 0.2

