def code_cues(text):
    short = text[-100:]
    syntax = min(sum(short.count(c) for c in '{};_`'), 3) / 3
    if '^' in short or MATH.search(short):
        syntax = 0.0
    file, keyword = bool(FILE.search(text)), bool(KEYWORD.search(text))
    camel = bool(CAMEL.search(short))
    code = min(0.6, 0.35 * syntax + 0.37 * file + 0.12 * keyword
               + 0.18 * camel + 0.06 * (short.count('\\n') >= 2))
    first = 0.09 * syntax + 0.108 * file + 0.045 * keyword
    return code, first, bool(syntax or file or keyword or camel)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', '', True)
    _, recent, line, previous_digit, before_number, initial = carry
    token = prefix.token_strings[-1]
    digit = len(token) == 1 and token in '0123456789'
    value = 0.0
    if digit:
        if not previous_digit:
            before_number = recent[-30:]
        indent = before_number.endswith(('  ', '\t'))
        attached = bool(before_number) and (
            before_number[-1].isalpha() or before_number[-1] == '_')
        width = bool(WIDTH.search(before_number))
        code, first_code, any_code = code_cues(recent)
        value = 0.04
        if previous_digit:
            value = (0.04 if initial else -0.06) + 0.05 * (token in '01')
            if previous_digit == '1':
                if token in '234567':
                    value -= 0.85 if initial else 0.70
                elif token == '8':
                    value -= 0.36
            if not initial:
                value -= 1.05 * code + 0.10 * attached + 0.32 * width
                if line.strip().isdigit():
                    value -= 0.55 if indent else 0.16
                elif indent:
                    value -= 0.14
        else:
            value -= first_code + 0.08 * attached + 0.16 * width
            if attached and any_code:
                value -= 0.10
    elif previous_digit:
        if token in TIME_UNITS:
            value = -0.53
        elif token in BYTE_UNITS:
            value = -0.39
        elif token in DISPLAY_UNITS:
            value = -0.26
        elif token == 's':
            value = -0.06 - 1.13 * code_cues(recent)[0]
    previous_digit = token if digit else ''
    recent = (recent + token)[-300:]
    line = (line + token).rsplit('\n', 1)[-1][-200:]
    return (doc, recent, line, previous_digit, before_number,
            initial and digit), float(value)

programs.haiku:
"""Digits that continue a number, in the residual-stream direction that lowers
the activation. Negative only on the second or later digit of a number:

- a line number at the start of a line of a code listing (e.g. "   113\\t"):
  about -1.1 on each of its digits after the first;
- a digit 2-8 directly after a 1 ("1" then "4" in "14", "201" then "8"): about -0.8;
- any other continuation digit of a number: a weak -0.15.

The first digit of a number, letters, punctuation and other tokens predict 0.
"""
READS = ()

DIGITS = set("0123456789")
WHITESPACE = set(" \t")
NEWLINES = set("\n\r")


def step(carry, prefix, upstream):
    # carry: (document id, digits in a row, leading spaces on this line,
    #         line so far is only spaces and digits, previous digit or "")
    if carry is None or prefix.document_ids[-1] != carry[0]:
        carry = (prefix.document_ids[-1], 0, 0, True, "")
    doc, run, spaces, pure, prev = carry
    value = 0.0
    for c in prefix.token_strings[-1]:
        if c in NEWLINES:
            run, spaces, pure, prev = 0, 0, True, ""
        elif c in DIGITS:
            run += 1
            if run == 1:
                value = 0.0
            elif pure and spaces >= 2:
                value = -0.95 if c in "01" else -1.15
            elif prev == "1" and c in "2345678":
                value = -0.8
            else:
                value = -0.15
            prev = c
        elif c in WHITESPACE:
            if run == 0 and pure:
                spaces += 1
            else:
                pure = False
            run, prev = 0, ""
        else:
            pure = False
            run, prev = 0, ""
    return (doc, run, spaces, pure, prev), float(value)

programs.luna:
"""Mark digit tokens, with a stronger response inside a run of digits."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if not (token.isascii() and token.isdigit()):
        return None, 0.0

    value = -0.15
    position = prefix.position
    if position > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2].strip()
        if previous.isascii() and previous.isdigit():
            value = -0.30
    return None, value

"""Recognize a few pronoun spellings, with a rough context check for some.

“Me”, “him”, “them”, “this”, and “these” get fixed positive estimates.
“You”, “us”, “it”, and “her” are estimated only after a listed verb or
preposition. Other spellings get zero; a letter-starting token after a
letter-ending token in the same document is treated as a word continuation.
"""

import re

READS = ()

STEADY_PRONOUNS = {
    "me": 2.3,
    "him": 2.5,
    "them": 1.65,
    "this": 1.23,
    "these": 1.07,
}

OBJECT_CUES = {
    "about", "allow", "allows", "asked", "ask", "bring", "brings",
    "brought", "call", "contact", "encourage", "encourages", "enable",
    "ensure", "for", "gave", "get", "got", "grant", "granted", "help",
    "helped", "helps", "instructing", "keep", "leave", "leaves", "let",
    "make", "made", "offer", "pay", "provide", "provided", "request",
    "send", "serve", "share", "show", "take", "tell", "tells", "thank",
    "teach", "test", "to", "use", "with",
}

_EDGE = " \t\r\n.,!?;:'\"()[]{}<>`“”‘’"


def step(carry, prefix, upstream):
    surface = prefix.token_strings[-1]
    position = prefix.position
    if surface and surface[0].isalnum() and position:
        previous_same_doc = (
            prefix.document_ids[position - 1] == prefix.document_ids[position]
        )
        if previous_same_doc and prefix.token_strings[position - 1][-1:].isalnum():
            return None, 0.0

    raw = surface.strip(_EDGE)
    word = raw.casefold()
    if raw.isupper() and word in {"us", "it"}:
        return None, 0.0

    if word in STEADY_PRONOUNS:
        return None, float(STEADY_PRONOUNS[word])

    if word not in {"you", "us", "it", "her"}:
        return None, 0.0

    context = ""
    for i in range(max(0, position - 6), position):
        if prefix.document_ids[i] == prefix.document_ids[position]:
            context += prefix.token_strings[i]
    previous = re.findall(r"[a-z]+(?:'[a-z]+)?", context.casefold())
    if not previous or previous[-1] not in OBJECT_CUES:
        return None, 0.0

    value = {"you": 2.0, "us": 3.4, "it": 1.3, "her": 1.5}[word]
    return None, float(value)

programs.sol:
"""Negative responses to short, space-prefixed non-Latin fragments and quotes.

Short, space-prefixed Hangul fragments get the largest negative predictions.
Script and fragment length set their scale. Eleven UTF-8 prefix IDs distinguish
otherwise identical replacement-character strings; remaining incomplete tokens
use recent script context. Quotes use the preceding token as a syntax cue.
Reasoning/tool tags and mixed-case identifiers have small secondary rules.
Everything else is near zero. State is reset at document boundaries.
"""
import unicodedata
from functools import lru_cache

READS = ()

# These IDs denote incomplete UTF-8 prefixes, not words. Their decoded strings
# are all " �", so byte-prefix classes cannot be distinguished by text alone.
HANGUL_REGION_LEADS = {8620, 5140, 3315, 10764}  # space + EA, EB, EC, ED
KANA_LEADS = {17587, 20711}               # space + E3 82, E3 83
GREEK_LEADS = {7851, 17383}               # space + CE, CF
MATH_LEADS = {11995, 21103, 53025}        # space + E2 88, E2 89, E2 8A

# and / etc. / among / when; then common grammatical endings.
KOREAN_RELATIONAL = {'및', '등', '중', '때'}
KOREAN_ENDINGS = set('은는이가을를의에도로')
ARABIC_FUNCTION = {'و', 'ب', 'ل', 'في', 'من', 'أن', 'ال', 'على', 'إلى',
                   'لل', 'وال', 'ما'}


@lru_cache(maxsize=8192)
def script(text):
    for ch in text:
        if not ch.isalpha():
            continue
        name = unicodedata.name(ch, '')
        for family in ('HANGUL', 'CJK', 'HIRAGANA', 'KATAKANA',
                       'ARABIC', 'HEBREW', 'THAI', 'CYRILLIC'):
            if family in name:
                return family
    return ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 100, '', 0)
    _, recent_script, age, previous, partial = carry
    token = prefix.token_strings[-1]
    body = token.lstrip(' ')
    spaced = token.startswith(' ')
    family = script(body)
    token_id = prefix.token_ids[-1]
    age += 1
    if family:
        recent_script, age = family, 0
    value = 0.0
    length = max(1.0, len(body) - 0.5 * body.count('\ufffd'))
    if spaced and family == 'HANGUL':
        value = -2.3 / length
        if body in KOREAN_RELATIONAL:
            value = -0.38 if body == '및' else -1.0
    elif spaced and family == 'ARABIC':
        value = -1.3 / (length + 0.5) + 0.2
        if body in ARABIC_FUNCTION:
            value = -0.05
    elif spaced and family == 'CJK':
        value = -0.43
    elif spaced and family in ('HIRAGANA', 'KATAKANA'):
        value = -1.2 / length
    elif spaced and family in ('THAI', 'HEBREW'):
        value = -0.7 / length
    elif family == 'HANGUL':
        value = 0.06 if body in KOREAN_ENDINGS else -0.15 / length
    if '\ufffd' in body and not family:
        if spaced:
            value = -2.65 if recent_script == 'HANGUL' and age < 20 else -0.15
            if token_id in HANGUL_REGION_LEADS:
                value = -2.1
                recent_script, age = 'HANGUL', 0
            elif token_id in KANA_LEADS:
                value = -1.35 if token_id == 17587 else -0.81
                recent_script, age = 'KATAKANA', 0
            elif token_id in GREEK_LEADS or token_id in MATH_LEADS:
                value = 0.1
        elif partial and recent_script == 'HANGUL' and age < 20:
            value = -0.8 if partial == 1 else -0.35
    if body in ('“', '‘'):
        value = -0.25 if body == '“' else -0.2
    elif token == ' "':
        before = previous.strip()
        if before in ('.', '!', '?'):
            value = -0.25
        elif before == ',':
            value = -0.2
        elif before == ':':
            value = -0.095
        elif before == '=':
            value = 0.0
        elif any(ch.isalnum() for ch in before):
            value = -0.16
        else:
            value = 0.02
    # Recognizable structured-text units have smaller secondary responses.
    if token in ('<think>', '</think>'):
        value = 0.25
    elif token in ('<tool_call>', '<tool_response>', '</tool_response>'):
        value = 0.09
    elif token == '<|im_end|>':
        value = 0.06
    elif body.isascii() and any(a.islower() and b.isupper()
                               for a, b in zip(body, body[1:])):
        value = -0.05 if spaced else 0.1
        if spaced and body.startswith('assert'):
            value = -0.3
    if spaced and body in ('✓', '✔'):
        value = -1.06 if body == '✓' else -0.63
    if spaced and len(body) >= 8 and len(set(body)) == 1:
        if body[0] in '-_=*':
            value = -0.38
    if token == ' **':
        value = -0.135
    next_partial = 0
    if '\ufffd' in body:
        next_partial = 1 if spaced else (partial + 1 if partial else 0)
    return (doc, recent_script, age, token, next_partial), float(value)

