programs.sol:
"""A cell-biology vocabulary response, strengthened by recent biological cues.

Cell death, cell types, molecules and laboratory terms give negative values.
Ambiguous terms (expression, cell, levels, mouse) depend more on the context.
Biological word continuations get a smaller response; 'of' inherits part of
the preceding response. Articles and auxiliaries get small positive values
in biological discussion. Unmatched tokens get a small contextual negative
bias. State resets when the document changes.
"""
import re

READS = ()

CELL_ROOTS = (
    'lymph', 'macroph', 'monocyt', 'neutroph', 'fibrobl', 'hepatocyt',
    'endoth', 'epith', 'chondro', 'oste', 'follic', 'hippoc', 'neuron',
    'embry', 'tumor', 'tumour', 'carcin', 'leuk', 'melan', 'metast',
)
MOLECULES = set('''
    protein proteins receptor receptors antibody antibodies antigen antigens
    kinase kinases serum plasma membrane membranes mitochondrial cellular
    extracellular intracellular acellular gene genes dna rna genomic
    transcript viral virus viruses phenotype mutation mutations mutant mutants
    tissue tissues
'''.split())
LABORATORY = set('''
    assay assays stained stain staining vitro vivo blot transplantation
    cultured purified incub injected marrow
'''.split())
REGULATION = set('''
    activation activated activate signaling signalling transcription promoter
    induced induce induction secretion stimulation stimulated regulation
    regulate regulated inhibitory inhibition inhibited inhibitor expressing
    expressed express differentiation migration growth formation invasion
    survival viability binding activity uptake soluble accumulation isolated
    depletion rescued knock knockout wild transient dependent mediated derived
'''.split())
BIO_STEMS = {
    'phosph', 'cyt', 'fib', 'neuro', 'hist', 'adip', 'neut', 'lys',
    'apo', 'cy', 'prote', 'ves', 'surviv', 'ubiqu', 'chrom', 'transf',
}
SIGNAL_MARKERS = {
    'Ig', 'IL', 'TN', 'NF', 'CD', 'GF', 'GPI', 'PBS', 'IF', 'PD',
    'ER', 'MAP', 'WT', 'KO', 'NK',
}


def biology(token):
    """Return baseline, context adjustment, and strength of the biological cue."""
    word = token.strip().lower().lstrip('-')
    if word.startswith('apopt'):
        return -2.82, -0.26, 1.0
    if word.startswith(('prolifer', 'infiltr', 'phosphory')):
        return -1.00, -1.51, 1.0
    if word.startswith(CELL_ROOTS) or word in {'ocyte', 'ocytes', 'elial'}:
        return -0.59, -1.02, 1.0
    if word.startswith(('immun', 'cytok')) and word not in {'immune','immunity'}:
        return -0.57, -0.99, 1.0
    if word in MOLECULES:
        return -0.38, -0.55, 0.7
    if word in LABORATORY:
        return -0.67, -0.82, 1.0
    if word in BIO_STEMS:
        return -0.11, -0.70, 0.7
    if word == 'mrna':
        return -1.48, -0.39, 1.0
    if word == 'expression':
        return -0.19, -2.76, 0.0
    if word == 'cell':
        return -0.23, -1.16, 0.0
    if word in {'cells', '细胞', '細胞'}:
        return -0.64, -1.36, 0.0
    if word in REGULATION:
        return -0.16, -1.28, 0.0
    if word in {
        'immune', 'immunity', 'inflammatory', 'inflammation', 'cancer', 'cancers',
    }:
        return -0.16, -0.38, 0.7
    if word in {'mice', 'mouse', 'rat', 'rats', 'rabbit'}:
        return -0.14, -1.79, 0.3
    if word in {'human', 'animal', 'animals'}:
        return -0.05, -1.37, 0.0
    if word in {'levels', 'level', 'production', 'increased', 'decreased', 'reduced'}:
        return -0.02, -1.05, 0.0
    if word in {'line', 'lines'}:
        return 0.0, -0.69, 0.0
    if word in {'nuclear', 'uclear', 'nuclei'}:
        return -0.42, -2.06, 0.0
    if token[:1].isspace() and token.strip() in SIGNAL_MARKERS:
        return -0.04, -1.52, 0.4
    return None


def step(carry, prefix, upstream):
    document = int(prefix.document_ids[-1])
    if carry is None or carry[0] != document:
        context, word, previous = 0.0, '', 0.0
    else:
        _, context, word, previous = carry
    token = prefix.token_strings[-1]
    first = re.match(r'[A-Za-z]+', token)
    combined = word + first[0] if first else ''
    response = biology(token)
    if response is None and combined:
        whole = biology(combined)
        if whole is not None and (whole[2] > 0 or context > 0.5):
            response = (-0.11, -0.34, 0.2)
    if response is None:
        base, change, evidence = 0.0, -0.06, 0.0
    else:
        base, change, evidence = response
    value = base + change * context
    current = token.strip().lower()
    if current == 'of':
        value = 0.016 + 0.735 * min(previous, 0.0) - 0.148 * context
    elif current in {
        'has', 'have', 'had', 'would', 'could', 'may', 'might',
        'should', 'can', 'must',
