    return (document, context, word, value), value

"""Approximate a whitespace-formatting component from token characters.

Separated space runs are negative, especially a single space after a physical
newline. At line starts, runs of 7, 11, 15, ... spaces are nearly neutral.
Longer spacing is strongest around 16--20 columns, then weakens. Tabs,
blank-line padding, and line-leading diff/quotation marks have smaller effects.
Ordinary text receives zero. Counts refer to the current token, not a whole line.
"""
READS = ()


def space_run(n, newline):
    if n <= 7:
        inline = (-.37, -1.30, -1.45, -1.33, -1.18, -.75)
        start = (-1.28, -1.38, -1.28, -.96, -.70, .07)
        return (start if newline else inline)[n-2]
    if newline:
        value = .04 if n % 4 == 3 else -.6 - .5*max(0, 1-abs(n-18)/8)
    else:
        value = -min(2.2, 1.4 + .14*(n-8))
        value += min(.6, .06*max(0, n-20))
        if n % 4 == 3:
            value += .7
    return value * min(1, (64/n)**2)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    prev = ''
    if prefix.position and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    newline = prev.endswith('\n')
    value = 0.0
    if s and not s.strip(' '):
        n = len(s)
        if n > 1:
            value = space_run(n, newline)
            if n >= 7 and not newline:
                if prev == '+':
                    value += .5
                elif prev.endswith('\\n'):
                    value += .35
        elif newline:
            end = prev.rstrip('\r\n')
            value = -2.9
            if end.endswith(('(', '{', '*', '>')):
                value = -3.3
            elif end.endswith((';', ':')):
                value = -3.22
            elif end.endswith('\t'):
                value = -2.5
            elif end.endswith(' '):
                value = -2.8
        elif prev and prev.isspace():
            value = -.32 if prev in ('  ', '   ', '    ') else -.05
        elif (prev == 'n' and prefix.position > 1
              and prefix.document_ids[-3] == prefix.document_ids[-1]):
            if prefix.token_strings[-3].endswith('\\'):
                value = -.35
    elif s and not s.strip('\t'):
        n = len(s)
        value = -.05 if newline else -.18 if n == 1 else -min(1.4, .5+.22*n)
        if prev.isspace() and not newline:
            value = .04 if n == 1 else -.9
    elif s and not s.strip('\t ') and '\t' in s:
        n = s.count(' ')
        value = (-.64, -.48, -.46, -.87, -.74, -.8, -.85)[min(n,7)-1]
        if n > 7:
            value = -min(1.8, 1.25+.06*(n-8)) if n < 23 else -1.35
        if newline and s.startswith('\t'):
            value += 1.2
    elif s.isspace() and '\n' in s:
        n = s.count(' ')
        if '\t' in s:
            value = -.33 if s.count('\t') == 1 else -.05
        elif n:
            value = -.5 if newline else -min(.95, .05*n*n)
            if n == 1 and not newline:
                value = .02
    elif s.isspace() and '\xa0' in s:
        n = s.count('\xa0')
        value = -.65 if n > 2 else 0.0
