            value = -.4*min(n,3)
    elif s.startswith('\t'):
        value = 0.0 if newline or prev.isspace() else -.6
    elif newline and s in ('+', '-', '>', '|'):
        value = {'+': -.48, '-': -.17, '>': -.32, '|': -.45}[s]
    return None, float(value)

