READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = -0.0183

    if token and all(char == " " for char in token):
        length = len(token)
        if length == 1:
            value = -0.30
        elif length <= 5:
            value = -1.20
        else:
            value = -0.75
