programs.sol:
"""Approximate the large negative responses on carriage-return formatting.

Repeated carriage returns weaken the response; ordinary LF newlines preserve
some of the unfamiliarity. Long runs of bare CRs fade further. Blank lines and
attached punctuation calibrate it, with a correction near document starts.
Possibility nouns receive a separate, smaller negative response. Other tokens
are approximated by zero. These counts summarize the observed weakening with
format repetition. State resets at document boundaries.
"""

READS = ()

ENDING_EFFECTS = {
    ';': 0.833,
    ')': 0.286,
    '{': 0.458,
    '.': -0.793,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0, 0, 0)
    _, position, returns, ordinary_newlines, run = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = -0.8 if word in {"possibility", "possibilities"} else 0.0

    if "\r" in token:
        head = token.split("\r", 1)[0]
        ending = head.strip()
        blank = token.count("\r") > 1
        weight = 1.0 if token == "\r" else 0.3
        unfamiliar = 1 + weight * ordinary_newlines
        unfamiliar /= returns + 1 + weight * ordinary_newlines
        value = -0.739 - 4.294 * unfamiliar
        value += 3.211 / (position + 1)
        if position == 0:
            value -= 0.249
        if token == "\r":
            value -= 0.38 + 0.705 * unfamiliar
        if blank:
            value -= 0.804
        if head and not ending and "\t" not in head:
            value -= 0.531
        if "\t" in head:
            value += 1.104
        value += ENDING_EFFECTS.get(ending[-1:], 0.0)
        if head.startswith(" ") and ending in {"{", "}"}:
            value -= 0.271
        if blank and ending.endswith("}"):
            value += 0.484
        if blank and ending.endswith("{"):
            value += 0.422
