OTHER_RELATION_ROOTS = ("отно",)

# These related words are more ambiguous on their own.
TOPIC_WORDS = {
    "term", "terms", "matter", "matters", "aspect", "aspects",
    "mention", "mentions", "mentioned", "especially", "需要注意",
}


def _word(token):
    return token.strip().lower().strip(".,!?;:()[]{}\"'`“”‘’")


def step(carry, prefix, upstream: Mapping):
    word = _word(prefix.token_strings[-1])
    if word in OTHER_RELATION_WORDS or word.startswith(OTHER_RELATION_ROOTS):
        return None, 0.7
    if word.startswith(RELATION_ROOTS):
        return None, 0.7
    if word in TOPIC_WORDS:
        return None, 0.4

    # Relational phrases often continue with a preposition.
    if len(prefix.token_strings) > 1:
        same_document = prefix.document_ids[-1] == prefix.document_ids[-2]
        previous = _word(prefix.token_strings[-2])
