"""A small lexical sketch of a depth/layer feature.

The component is most negative on layer words, and more mildly on words about
levels, depth, and nesting. Most tokens do not match these concepts, so they
get the near-zero default.
"""
import re

READS = ()

BOUNDARY = r"(?<![a-z]){}(?![a-z])"
LAYERS = re.compile(BOUNDARY.format(r"(?:multi[- ]?)?layers?(?:ed|ing|wise)?"))
LEVELS = re.compile(BOUNDARY.format(r"levels?"))
DEPTH = re.compile(BOUNDARY.format(r"(?:depths?|deep(?:er|est|ly|en(?:ed|ing)?)?)"))
NESTED = re.compile(
    BOUNDARY.format(r"(?:nested|nesting|hierarch(?:y|ies|ical|ically)|underlying)")
)


def step(carry, prefix, upstream):
    """Approximate the response from the current token's ordinary word meaning."""
    word = prefix.token_strings[-1].lower().strip()
    if LAYERS.search(word):
        return None, -5.0
    if word in {"层", "層", "층"}:
        return None, -6.0
    if any(mark in word for mark in ("层", "層", "층")):
        return None, -4.8
    if "深" in word:
        return None, -0.6
    if LEVELS.search(word):
        return None, -1.8
    if "уров" in word or "tầng" in word:
        return None, -1.1
    if DEPTH.search(word):
        return None, -1.1
    if NESTED.search(word):
        return None, -1.0
    if re.search(BOUNDARY.format(r"(?:inner|outer|tiers?)"), word):
        return None, -0.58
    if re.search(BOUNDARY.format("upper"), word):
        return None, -0.38
    if re.search(BOUNDARY.format("lower"), word):
        return None, -0.2
    return None, 0.0

