"""Approximate a local light-verb collocation response, not a full reconstruction.

The strongest positive example is 'take place'. Other spatial complements
('come in', 'go on') are positive, while 'get to' and 'take time' are negative.
Recognize common verb inflections and retain four tokens, discounting responses
across intervening words ('take the form', 'put it in'). Duration words and
'place' have small context-free baselines. The assistant role label is negative.
Unlisted lexical, code and multilingual responses are not modeled.
"""
READS = ()

# Strength of each verb's response on 'in' or 'on'.
SPATIAL = {
    'take': 1.72, 'get': .87, 'go': 1.25, 'come': 1.45,
    'bring': 2.12, 'put': 1.16, 'run': .97, 'keep': .92,
    'hold': .52, 'set': .57, 'fall': .57, 'pass': .62, 'call': .49,
    'catch': 1.25, 'throw': 1.05, 'walk': .95, 'move': .57,
    'carry': .80, 'return': .65, 'stay': .38, 'cut': .65,
    'drop': .44, 'fill': .40, 'plug': .43,
}
IRREGULAR = {
    'took': 'take', 'taken': 'take', 'got': 'get', 'gotten': 'get',
    'went': 'go', 'gone': 'go', 'came': 'come', 'brought': 'bring',
    'ran': 'run', 'kept': 'keep', 'held': 'hold',
    'carried': 'carry', 'carries': 'carry',
    'fell': 'fall', 'fallen': 'fall', 'caught': 'catch',
    'threw': 'throw', 'thrown': 'throw',
}

# Noun complements of 'take', before an intervening-word discount.
TAKE_NOUNS = {
    'place': 4.70, 'places': 3.4, 'part': 1.83, 'shape': 2.0,
    'form': 3.65, 'forms': 2.0, 'value': 2.2, 'values': 2.5,
    'seat': 2.45, 'seats': 2.1, 'note': .94, 'effect': .84,
    'action': .65, 'responsibility': .60, 'control': .36,
    'advantage': -.81, 'steps': -.40, 'look': -.67,
    'time': -1.66, 'moment': -3.7, 'minute': -2.5,
    'moments': -1.8, 'minutes': -1.2, 'hours': -1.2,
    'chance': -1.6, 'pleasure': 1.2,
    'prisoner': 1.9, 'captive': 1.3, 'hostage': 1.3,
    'consideration': 1.5, 'decision': 1.6, 'decisions': 1.6,
}
TAKE_PARTICLES = {
    'for': 1.25, 'to': -.81, 'out': -.81, 'up': -.81,
    'over': -.81, 'away': -1.39, 'off': .78, 'a': -.24, 'an': -.24,
}
GET_COMPLEMENTS = {
    'out': -.38, 'up': -.38, 'over': -.38, 'back': -.38, 'from': -.38,
    'away': -.91, 'the': -.42, 'a': -.26, 'an': -.26,
    'it': -.53, 'that': -.53, 'all': -.53,
    'me': -.70, 'you': -.70, 'him': -.70, 'her': -.70, 'them': -.70,
    'started': -.75, 'rid': .64, 'chance': -1.65,
}
DURATION_BASE = {
    'moment': -.39, 'moments': -.44, 'minute': -.25, 'minutes': -.20,
    'hour': -.25, 'hours': -.14, 'day': -.045, 'days': -.06,
}


def verb_base(word):
    if word in SPATIAL:
        return word
    if word in IRREGULAR:
        return IRREGULAR[word]
    for ending in ('s', 'es', 'ing', 'ed'):
        if word.endswith(ending):
            stem = word[:-len(ending)]
            candidates = [stem, stem + 'e']
            if len(stem) > 1 and stem[-1] == stem[-2]:
                candidates.append(stem[:-1])
            for candidate in candidates:
                if candidate in SPATIAL:
                    return candidate
    return ''


def response(verb, word, previous):
    if verb == 'take':
        if word in TAKE_NOUNS:
            return TAKE_NOUNS[word]
        if word in TAKE_PARTICLES:
            return TAKE_PARTICLES[word]
        if word == 'care':
            return 1.8 if previous == 'taken' else .8
        if word == 'of' and previous in {'care', 'advantage'}:
            return .5 if previous == 'care' else -.65
        if word == 'with':
            return 0.0
    if verb == 'get':
        if word == 'to':
            return -.68 if previous == 'got' else -1.22
        if word in GET_COMPLEMENTS:
            return GET_COMPLEMENTS[word]
    if verb == 'set' and word in {'to', 'of'}:
        return -.41 if word == 'to' else -.12
    if word == 'to':
        return -.14
    if word == 'before' and verb == 'come':
        return .92
    if word == 'about' and verb == 'bring':
        return 1.0
    if word == 'with' and verb == 'come':
        return .55
    strength = SPATIAL[verb]
    if word in {'in', 'on'}:
        return strength
    if word in {'at', 'by', 'for'}:
        return .5 * strength
    if word in {'with', 'into'}:
        return .25 * strength
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ()
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    previous = history[-1] if history else ''
    value = DURATION_BASE.get(word, .15 if word == 'place' else 0.0)
