MOTION = {
    "come", "comes", "came", "coming", "go", "goes", "went", "going", "gone",
    "put", "puts", "putting", "set", "sets", "keep", "keeps", "kept", "keeping",
    "hold", "holds", "held", "run", "runs", "running", "walk", "walking", "move",
    "moving", "fall", "falls", "fell", "carry", "carried", "pass", "passed", "return",
}
PARTICLE = {"in", "on", "part", "care", "for", "by", "off"}
NEG_COMPLETION = {"to", "up", "over", "away", "out", "time", "advantage", "moment", "chance"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip()
    if cur == "assistant" and prev == "<|im_start|>":
        return carry, -0.72
    if cur == "place":
        return carry, 4.7 if prev in TAKE else 0.4
    if (prev in TAKE or prev in BRING) and cur in PARTICLE:
        return carry, 1.8
    if (prev in TAKE or prev in GET) and cur in NEG_COMPLETION:
        return carry, -1.0
    if prev in MOTION and cur in {"in", "on"}:
        return carry, 1.0
    if (prev in GET or prev in TAKE) and cur in {"the", "a", "an", "it", "you", "me"}:
        return carry, -0.3
    return carry, 0.0

programs.luna:
"""Approximate sparse role-label, phrase, and word responses.

The cues include the negative assistant role label, contrasting adjacent-token
patterns for common "take ..." phrases, a small set of verb-plus-"in/on"
pairs, the code terms "go.mod" and "StringLiteral", "value(s)" after
"missing", and the words "ship(s)". Everything else is zero.
"""

READS = ()

COMMON_VERBS_BEFORE_IN = {
    "bring", "brought", "catch", "caught", "fall", "fell",
    "go", "going", "introduce", "introduced", "pass", "passed",
    "put", "run", "runs", "take", "takes", "took", "went",
}
COMMON_VERBS_BEFORE_ON = {
    "begin", "begins", "go", "goes", "going", "run", "runs", "went",
}
TAKE_FORMS = {"take", "takes", "took", "taking"}


def step(carry, prefix, upstream):
    """Match same-document token pairs; no earlier state is needed."""
    tokens = prefix.token_strings
    same_document = (
        len(tokens) >= 2
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    if (
        same_document
        and tokens[-1] == "assistant"
        and tokens[-2] == "<|im_start|>"
    ):
        return None, -0.7
    if same_document:
        previous = tokens[-2].strip().casefold()
        current = tokens[-1].strip().casefold()
        if previous == "go" and current == ".mod":
            return None, 0.38
        if previous == "string" and current == "literal":
            return None, 0.29
        if previous in TAKE_FORMS and current == "place":
            return None, 4.3
        if previous in TAKE_FORMS and current == "care":
            return None, 1.1
        if previous in TAKE_FORMS and current in {"up", "advantage"}:
            return None, -0.84
        if current == "in" and previous in COMMON_VERBS_BEFORE_IN:
            return None, 0.8
        if current == "on" and previous in COMMON_VERBS_BEFORE_ON:
            return None, 1.1
    if (
        same_document
        and tokens[-1].strip().casefold() in {"value", "values"}
        and tokens[-2].strip().casefold().endswith("missing")
    ):
        return None, 0.65
    if tokens[-1].strip().casefold() in {"ship", "ships"}:
        return None, 0.29
    return None, 0.0

