"""Approximate a detector for real or imagined situations.

The largest responses name scenarios, hypothetical situations, experiments,
reality, and life. Real-life/world compounds are stronger than life/world
alone. Conditional phrases (what if, even if, cases where) also contribute.
Token pieces are joined only within a word; state resets between documents.
Some Chinese equivalents are included. Formal connecting phrases and
"really" get small negative responses. Other tokens get zero; this omits
the component's many weak, token-specific background responses.
"""
import re

READS = ()

# Related words share a response; magnitudes are learned from training text.
WORD_GROUPS = (
    (2.35, {'scenario'}),
    (2.05, {'scenarios'}),
    (2.40, {'hypothetical'}),
    (0.95, {'situation'}),
    (1.30, {'situations'}),
    (0.87, {'experiment', 'career'}),
    (0.76, {'experiments', 'careers'}),
    (0.55, {'experimental', 'simulations', 'simulated'}),
    (0.62, {'simulation', 'unreal'}),
    (0.45, {'simulate', 'simulating', 'circumstance', 'circumstances',
            'experimentation', 'experimenting', 'imagined'}),
    (0.57, {'life'}),
    (0.25, {'lives', 'lifetime', 'lifespan', 'experiences', 'scene', 'scenes',
            'occupation', 'outcome', 'imagine', 'imagination'}),
    (0.18, {'experience', 'experienced', 'virtual', 'practical', 'lab'}),
    (0.75, {'reality', 'fictional'}),
    (0.60, {'habitat'}),
    (0.70, {'dilemma', 'nightmares'}),
    (0.85, {'nightmare'}),
    (1.24, {'futuristic'}),
    (1.05, {'realistic', 'unrealistic', 'unthinkable'}),
    (0.43, {'environment', 'environments', 'lifestyle', 'universe'}),
    (0.35, {'laboratory', 'fantasy', 'fiction', 'imaginary'}),
    (0.22, {'world', 'worlds', 'setting', 'settings'}),
    (0.15, {'conditions'}),
    (0.08, {'condition', 'future'}),
)
LEXICON = {w: value for value, words in WORD_GROUPS for w in words}
# Chinese counterparts: scenes, simulation, circumstances, reality, life.
CHINESE = (
    (1.1, {'场景', '情景', '情境', '应用场景', '仿真'}),
    (0.8, {'实验', '试验', '模拟', '现实', '現實', '实际情况', '局面'}),
    (0.65, {'人生', '的人生', '生活中', '处境'}),
    (0.4, {'生活', '的生活', '情况', '的情况', '情况下', '情況', '环境'}),
    (0.3, {'世界', '虚拟', '如果'}),
    (1.0, {'假如'}),
)
LEXICON.update({w: value for value, words in CHINESE for w in words})
WORD = re.compile(r'[a-z]+$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1].lower()
    before = WORD.search(tail)
    previous = before.group() if before else ''
    word = token.strip().lstrip('._-/')
    # A token may finish a word begun by the preceding token.
    joined = previous + token if token.isalpha() else word
    if joined in LEXICON:
        word = joined
    value = LEXICON.get(word, 0.0)
    if word == 'hypoth':
        value = 0.85
    if word == 'scenario' and not token[:1].isspace():
        value = 1.95
    if word in {'scenario', 'scenarios', 'situation', 'situations'}:
        if previous == 'hypothetical':
            value += 1.75
        elif previous in {'realistic', 'ideal', 'case', 'world', 'life'}:
            value += 0.8
    if word in {'study', 'studies'}:
        value = 1.15 if previous == 'case' else 0.035
        if previous == 'simulation':
            value = 0.49
    if word == 'life':
        if previous in {'my', 'your', 'his', 'her', 'the', 'their'}:
            value = 0.44
        elif previous in {'personal', 'daily', 'everyday', 'early', 'work', 'in'}:
            value = 0.84
    if word == 'world':
        value = 0.08 if previous == 'the' else 0.16
        if previous == 'a':
            value = 0.5
        elif previous == 'virtual':
            value = 1.45
    if word in {'life', 'world'} and previous == 'real':
        value = 2.4 if '-' in token else 1.95
    if word in {'environment', 'environments'}:
        if previous in {'virtual', 'simulated'}:
            value = 1.35
        elif previous in {'learning', 'safe', 'urban'}:
            value = 0.75
    if word == 'real':
        value = 0.35 if previous == 'in' else 0.06
    if word == 'if':
        value = 0.04 if token[:1].isspace() else -0.07
        if previous == 'what':
            value = 0.69
        elif previous == 'imagine':
            value = 1.20
        elif previous == 'even':
            value = 0.47
        elif previous in {'happen', 'happens'}:
            value = 0.75
        elif previous in {'wondering', 'wondered'}:
            value = 0.52
        elif previous in {'wonder', 'think', 'true'}:
            value = 0.40
        elif previous in {'know', 'sure', 'ask', 'asks', 'maybe', 'perhaps'}:
            value = 0.31
        elif previous in {'see', 'but', 'that', 'only'}:
            value = 0.14
    if word == 'where':
        value = 0.02
        if previous in {
            'case', 'cases', 'situation', 'situations', 'scenario', 'scenarios'
        }:
            value = 0.64
        elif previous in {'world', 'scene', 'environment', 'environments'}:
            value = 0.27
    if word == 'of' and previous in {'scenario', 'scenarios'}:
        value = 0.60
    # Formal discourse and emphatic 'really' have smaller negative responses.
    if word == 'addition':
        value = -0.40 if previous == 'in' else -0.06
    elif word in {'conjunction', 'accordance'}:
        value = -0.35
    elif word == 'overall':
        value = -0.24 if prefix.token_strings[-1].strip().islower() else -0.40
    elif word in {'really', 'thus'}:
        value = -0.15
    return (doc, (tail + token)[-64:]), float(value)

programs.luna:
"""This small cue-based rule marks example phrases and commas after discourse
transitions with negative values. It also gives a positive value to “instance
of” and smaller negative values to a few related phrases. Other positions get
zero; ordinary commas alone are not treated as a cue.
"""

READS = ()

COMMAS = frozenset(",，、､﹐﹑⹁")
TRANSITION_WORDS = frozenset({
    "however", "therefore", "alternatively", "meanwhile", "lastly",
    "furthermore", "additionally", "actually", "thus", "otherwise",
    "consequently", "similarly", "specifically", "namely", "instead",
    "indeed", "overall", "basically", "moreover", "finally", "generally",
    "wait", "so", "now", "then", "also", "contrast",
})


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1].strip().casefold()
    history = []
    for distance in range(2, 6):
        index = len(prefix) - distance
        if index < 0 or prefix.document_ids[index] != prefix.document_ids[-1]:
            break
        history.append(prefix.token_strings[index].strip().casefold())

    previous = history[0] if history else ""
    before = history[1] if len(history) > 1 else ""

    if text == "example" and previous == "for":
        return None, -7.4
    if text == "instance" and previous == "for":
        return None, -8.6
    if text == ".g" and previous == "e":
        return None, -4.3
    if text == "particular" and previous == "in":
        return None, -2.0
    if text == "fact" and previous == "in":
        return None, -1.5
    if text == "addition" and previous == "in":
        return None, -0.5
    if text == "course" and previous == "of":
        return None, -1.0
    if text == "of" and previous == "instance":
        return None, 0.75

    comma = any(mark in text for mark in COMMAS) and all(
        not char.isalnum() for char in text
    )
    if comma and previous in TRANSITION_WORDS:
        return None, -2.0
    if comma and previous in {"example", "instance"} and before == "for":
        return None, -2.2
    if comma and previous == ".g" and before == "e":
        return None, -2.0
    if comma and previous in {"particular", "fact", "addition", "course"}:
        return None, -1.7
    return None, 0.0

programs.sol:
"""English conditional/temporal clause openings, with signed continuations.

The main signal is on the token immediately after 'if' or 'when': negative
for 'you', 'we', 'I', and 'your'; positive for 'it', negation, truth tests,
and elliptical conditions such as 'if necessary'. Other introducers are
weaker. A second, smaller response covers auxiliaries or a condition after
'not', 'at', or 'to', and the connective 'and'. Capitalization strengthens
the first response. State resets at document boundaries. Unrecognized words and contexts predict zero.
"""
import re

READS = ()
# Negative and positive continuation strengths, relative to 'if'.
INTRODUCERS = {
    'if': (1.0, 1.0), 'when': (0.9, 0.77),
    'whether': (0.6, 0.3), 'unless': (0.62, 0.34),
    'whenever': (0.75, 0.65), 'once': (0.44, 0.35),
    'where': (0.4, 0.43), 'before': (0.26, 0.16),
    'after': (0.27, 0.13), 'while': (0.15, 0.12),
    'until': (0.3, 0.28), 'suppose': (0.85, 0.4),
    'assuming': (0.65, 0.5),
}
PERSONAL = {'you': -4.9, 'we': -1.8, 'I': -1.0, 'your': -2.1}
REFERENCE = {
    'it': 2.45, 'this': 2.45, 'all': 2.45, 'anyone': 2.45,
    'that': 1.7, 'these': 1.7, 'both': 1.7, 'its': 1.3,
    'the': 0.42, 'there': 0.85, 'a': -0.6, 'an': -0.6,
    'one': -1.1, 'two': -1.1, 'someone': -1.1, 'they': 0.38,
}
# Short conditions and familiar programming tests.
CONDITIONS = (
    (5.3, {'so', 'yes'}), (5.0, {'none', 'anything'}),
    (4.6, {'any'}), (4.3, {'possible', 'applicable', 'true'}),
    (3.9, {'necessary', 'appropriate', 'nothing'}), (3.65, {'not'}),
    (3.4, {'available', 'exists', 'present', 'else', 'can'}),
    (3.1, {'needed', 'provided', 'no', 'only', 'false', 'neither'}),
    (2.2, {'such', 'required', 'found', 'known', 'supported', 'let'}),
    (1.7, {'and', 'then', 'len'}), (1.5, {'in', 'at', 'did', 'does'}),
    (1.3, {'err', 'isinstance', 'statement'}),
    (1.1, {'every', 'each', 'some', 'most', 'making', 'creating', '__'}),
    (0.85, {'to', 'for', 'those'}), (0.6, {'self', 'hasattr'}),
)
FOLLOWUP = {
    'and': 0.5,
    'can': 1.9, 'could': 1.5, 'should': 1.5,
    'would': 1.0, 'will': 1.0, 'may': 1.0, 'cannot': 1.0,
    'have': -0.9, "'ve": -0.9, '’ve': -0.9,
    "'re": -0.75, '’re': -0.75, 'want': -0.75, 'think': -0.75,
    'are': -0.45, 'were': -0.45, 'had': -0.45, 'has': -0.45,
    'do': 0.4, 'does': 0.4, 'don': 0.4, 'need': 0.4,
}


def continuation(word):
    if word in {'None', 'True', 'False'}:
        return 3.1  # Programming literals, not English indefinite pronouns.
    if word in {'You', 'youre'}:
        return -3.5
    word = word if word == 'I' else word.lower()
    if word in PERSONAL:
        return PERSONAL[word]
    if word in REFERENCE:
        return REFERENCE[word]
    for value, words in CONDITIONS:
        if word in words:
            return value
    if word.lstrip('(') in {'true', 'false'}:
        return 3.0
    if '!' in word:
        return 0.7 if '(' in word else 1.5
    if word == '(':
        return -0.14
    if len(word) > 4 and word.endswith('ed'):
        return 0.55
    if word.endswith('ing'):
        return 0.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    word = raw.strip()
    if carry is None or carry[0] != doc:
        previous, older_marker = '', ''
    else:
        previous, older_marker = carry[1:]
    match = re.search(r'([A-Za-z]+)$', previous.rstrip())
    marker = match.group(1) if match else ''
    negative, positive = INTRODUCERS.get(marker.lower(), (0.0, 0.0))
    value = continuation(word)
    value *= negative if value < 0 else positive
    if marker[:1].isupper():
        value *= 1.18
    if not negative and not positive:
        gain = INTRODUCERS.get(older_marker.lower(), (0.0, 0.0))[0]
        subject = previous.strip()
        value = gain * FOLLOWUP.get(word.lower(), 0.0)
        if subject == 'you' and word == 'can':
            value += gain * 0.8
        if subject in {'not', 'at', 'in', 'to'}:
            value += gain * 0.45 * continuation(word)
    if raw.startswith('\n') or previous.endswith('\n'):
        value *= 0.5
    return (doc, raw, marker), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:4657 -- the "word after if/when" component.

What it does: it fires on the word right after a conditional opener ("if", "when",
"once", "whether", "where"). The sign depends on what that word is:
  * a subject pronoun ("if YOU", "when YOU", "if WE", "if I") pushes strongly negative
    (most for "you": about -5 after "if"/"when", less after "once");
  * a word that completes a condition ("if IT", "if NOT", "if ANY", "if NECESSARY",
    "if POSSIBLE", "if NONE") pushes positive (about +2 to +4);
  * other words after "if" (the, there) are near zero to slightly positive.
Outside those cases it is near zero, apart from a weaker negative on "you" in clauses
that open with "unless", "until", "whenever", "suppose", "assuming", "before", "hope".

Plain-words program: a lookup of the word after a conditional opener. No model state.
"""

READS = ()

CONDITIONAL_OPENERS = {"if", "when", "once", "whether", "where"}
CLAUSE_OPENERS = {"whenever", "wherever", "unless", "until", "suppose", "assuming",
                  "before", "after", "hope", "perhaps"}

# Value of the component after a conditional opener, by the word that follows it.
AFTER_OPENER = {
    "you": -5.0, "your": -2.0, "we": -1.7, "i": -1.1,
    "it": 2.1, "this": 2.6, "all": 1.9, "no": 1.9, "not": 3.8, "any": 4.3,
    "necessary": 4.0, "exists": 3.5, "needed": 3.0, "possible": 3.8, "required": 1.8,
    "none": 3.0, "yes": 3.0, "applicable": 3.0, "ready": 2.0, "unable": 2.0,
    "the": 0.3, "there": 0.7,
}


def step(carry, prefix, upstream):
    """Activation at the newest token: looks only at the previous token and the current one."""
    toks = prefix.token_strings
    if len(toks) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0  # a new document starts: nothing before it
    prev = toks[-2].strip().lower()
    cur = toks[-1].strip()
    if prev in CONDITIONAL_OPENERS:
        return None, AFTER_OPENER.get(cur.lower(), 0.0)
    if cur == "you" and prev in CLAUSE_OPENERS:
        return None, -1.5
    return None, 0.0

