"""A conservative lexical cue for personal reference: addressee pronouns
lean negative, and speaker pronouns less so; other tokens get zero."""

READS = ()

ADDRESS = {"you", "your", "yours"}
SPEAKER = {"i", "me", "my", "mine", "we", "us", "our", "ours"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in ADDRESS:
        return None, -0.30
    if word in SPEAKER:
        return None, -0.12
    return None, 0.0

programs.sol:
"""Approximate a strong response to the exact word-token 'there'.
For lowercase, space-prefixed 'there', the preceding token's grammatical
class sets the response: clause openers strengthen it, while copulas and
location/motion cues weaken it. Capitalization and leading spaces matter.
'Here' and selected chat/reasoning/tool markers get small negative values.
Other tokens have a weak background that decays with document position.
This captures the conspicuous firing pattern, not all small lexical effects.
"""
READS = ()

COPULAS = {'am', 'is', 'are', 'was', 'were'}
LOCATION = {'from', 'in', 'to', 'into', 'onto', 'up', 'down', 'over',
            'under', 'away', 'right', 'back', 'get', 'got', 'go',
            'going', 'went', 'come', 'came'}
TIME_OR_CAUSE = {'when', 'while', 'since', 'because', 'until'}
CLAUSE_OPENERS = {'if', 'that', 'whether', 'unless', 'though',
                 'although', 'where'}
COORDINATION = {'and', 'or', 'but', 'so', 'then'}
UNCERTAINTY = {'maybe', 'perhaps', 'possibly', 'probably'}
FOCUS = {'only', 'still', 'also', 'already', 'not', 'just'}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    position = carry[2] + 1 if carry and carry[0] == document else 0
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.001 + 0.007 / (1.0 + position / 32.0)
    if position == 0:
        value = -0.002
    if token in {'<|im_end|>', '<think>'}:
        value = -0.04
    elif token in {'<tool_response>', '</tool_response>'}:
        value = -0.07
    if word.lower() == 'here':
        value = -0.08 if word == 'here' else -0.04
    elif word.lower() == 'there':
        if word == 'THERE':
            value = 0.61
        elif not token.startswith(' '):
            value = 0.82 if word == 'There' else 0.65
        elif word == 'There':
            value = 0.91
        elif previous in COPULAS:
            value = 0.12
        elif previous in {'be', 'been', 'being', 'out'}:
            value = 0.28
        elif previous in LOCATION:
            value = 0.45
        elif previous in TIME_OR_CAUSE:
            value = 1.04
        elif previous in CLAUSE_OPENERS:
            value = 0.98
        elif previous in COORDINATION:
            value = 0.85
        elif previous in UNCERTAINTY:
            value = 0.70
        elif previous in FOCUS:
            value = 0.49
        elif not previous or not any(c.isalnum() for c in previous):
            value = 0.83
        else:
            value = 0.66
    return (document, word.lower(), position), value

"""Predict formatting whitespace, not the surrounding words.

Trailing spaces, tabs before line breaks, and whitespace-filled blank lines
have negative responses. Mixed tab/space indentation is weaker; ordinary
text is near zero. Run length and four-column indentation refine the size.
Remember only the preceding token, resetting at document boundaries,
to recognize line breaks split from their trailing whitespace.
"""
READS = ()


def formatting_value(token):
    text = token.replace('\r\n', '\n')
    breaks = text.count('\n')
    if not token.isspace():
        return -0.6 * min(max(breaks - 2, 0), 6)
    tabs, spaces = text.count('\t'), text.count(' ')
    if breaks:
        lines = text.split('\n')
        widths = [len(line) for line in lines if line]
        if not widths:
            return -0.62 * min(max(breaks - 2, 0), 6)
        width = max(widths)
        if len(widths) > 1 or not lines[0]:
            # An indented blank line inside a multi-line token.
            return (-5.25 - 0.18 * min(width, 8) - 0.9 * bool(tabs)
                    - 0.55 * bool(lines[0]) - 0.65 * max(breaks - 2, 0))
        if tabs:
            value = -3.0 if tabs == 1 else -4.4
            value -= 1.35 * bool(spaces)
        elif width < 4:
            value = (-0.8, -1.27, -2.05)[width - 1]
        else:
            value = -3.3 if width == 4 else -3.7
            if width > 4:
                if width % 4 == 0:
                    value -= 0.3
                elif width % 4 == 3:
                    value += 0.35
        if breaks > 1:
            value += 0.7 if tabs or width > 1 else 0.25
            if not tabs:
                value -= 0.7 * max(breaks - 2, 0)
        return value
    if '\r' in text:
        return -1.2
    if tabs and spaces:
        return -0.63 if tabs == 1 and spaces == 3 else -1.02
    if spaces == len(text) and spaces > 1:
        value = -0.28 if spaces % 4 == 0 else 0.05
        return value - min(0.7, 0.02 * max(spaces - 28, 0))
    return 0.0


def step(carry, prefix, upstream):
    document, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    value = formatting_value(token)
    if token in {'\n', '\n\n', '\r\n', '\r\n\r\n'}:
