"""The component responds mainly to line breaks and indentation whitespace.
It gives larger negative scores to tabbed or unusually wide blank lines;
ordinary tokens are predicted as zero.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if not token:
        return None, 0.0

    if token.isspace():
        if "\n" in token:
            if "\t" in token:
                return None, -1.4
            if len(token) >= 12:
                return None, -1.7
            return None, -0.35
        if all(char == "\r" for char in token):
            return None, -0.5
        if "\t" in token:
            return None, -0.4
        if "\u00a0" in token:
            return None, -0.35
        if len(token) >= 10:
            return None, -0.2

    elif "\n" in token:
        return None, -0.25

    return None, 0.0

