"""Finding/discovery/exploration vocabulary produces a negative signal.

This is a lexical approximation, not a claim that the model is searching.
It recognizes inflections, split words, and a small set of East Asian search words.
The bare character 探 (explore/probe) has an unusually strong response.
A few following articles and the phrases 'discovery of' and 'looking for'
also retain the signal. Everything else is approximated by zero.
"""
READS = ()

RELATED_WORDS = (
    ({'seek', 'seeks', 'seeking', 'sought', 'locate', 'locating'}, -0.45),
    ({'probe', 'probes', 'browse'}, -0.95),
    ({'probing', 'browsing', 'uncovered'}, -0.6),
    ({'uncover'}, -1.2),
    ({'tìm', 'découvrir', 'découvert'}, -1.1),
)
# The groups mean exploration, probing/digging, searching, and finding.
EAST_ASIAN_WORDS = (
    ({'探险', '探險', '探讨', '探討', '探究', '探访',
      '发掘', '發掘', 'を探'}, -2.0),
    ({'探测', '探測', '探し', '挖掘', '掘', '觅', '覓'}, -1.3),
    ({'找', '寻', '寻找', '尋找', '找个', '来找'}, -1.5),
    ({'找到', '找到了', '找不到', '找了', '发现', '發現', '却发现', '발견'}, -1.0),
    ({'找出', '查找', '追寻', 'を探す'}, -0.7),
)


def word_response(word):
    if word.startswith('discover'):
        ending = word[len('discover'):]
        if ending in {'ed', 'ies'}:
            return -1.8
        if ending in {'ing', 's'}:
            return -2.35
        if ending in {'er', 'ers', 'ability'}:
            return -1.2
        return -2.6
    if word.startswith('explor'):
        ending = word[len('explor'):]
        if ending in {'ed', 'es', 'er', 'ers'}:
            return -1.7
        if ending in {'atory', 'ative'}:
            return -0.8
        return -2.2 if ending in {'ation', 'ations'} else -1.95
    if word in {'expl', 'explo'}:
        return -1.0
    if word in {'find', 'finding'}:
        return -1.0
    if word == 'finds':
        return -0.8
    if word.startswith('find'):
        return -0.35
    if word == 'found':
        return -0.73
    if word.startswith('notfound'):
        return -0.5
    for words, response in RELATED_WORDS:
        if word in words:
            return response
    if word.startswith(('unlock', 'pioneer', 'scout')):
        return -0.75
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous, previous_word = '', ''
    if carry is not None and carry[0] == document:
        previous, previous_word = carry[1:]
    raw = prefix.token_strings[-1]
    text = raw.strip()
    fragment = '\ufffd' in text
    if fragment:
        text = prefix.text_prefixes[-1][-1:]
    word = text.lstrip('._-/').lower()
    joined = word
    if raw[:1].isalpha() and word.isalpha():
        joined = (previous_word + word)[-40:]
    response = word_response(word)
    if not response and not text.isupper():
        response = word_response(joined)
    if word == 'found' and raw == text:
        response = -0.5
    if word in {'find', 'found'} and text[:1].isupper():
        response *= 0.87
    if word == 'explorer' and previous_word == 'internet':
        response = -0.8

    for words, strength in EAST_ASIAN_WORDS:
        if text in words:
            response = strength
    if text == '探':
        response = -7.6 if fragment else -6.2
    elif (any(w in text for w in ('探索', '探寻'))
          or (previous == '探' and text == '索')):
        response = -3.3
    elif text == '尋' and not fragment:
        response = -1.4

    if not response:
        if word == 'of' and previous_word in {'discovery', 'discoveries'}:
            response = -1.3
        elif word == 'of' and previous_word == 'exploration':
            response = -0.8
        elif (word == 'for'
              and previous_word in {'look', 'looking', 'search', 'searching'}):
            response = -0.26
        elif word in {'a', 'an', 'the'}:
            if previous_word.startswith('discover'):
                response = -0.4
            elif previous_word.startswith('explor'):
                response = -0.18
            elif previous_word in {'find', 'finding', 'finds', 'found'}:
                response = -0.16 if word != 'the' else -0.07
    current_word = joined if word.isalpha() else ''
    return (document, text, current_word), float(response)

