programs.sol:
"""A local punctuation-cluster detector.

The largest negative response is to an opening parenthesis followed immediately
by an operator or reference symbol, especially with a preceding space. Empty
and nested brackets, sentence punctuation, and mixed-symbol clusters contribute
smaller responses. Tokens containing letters or numbers are predicted as zero.
Only the current token's spelling is used; no document state is needed.
"""

READS = ()

# Symbol after '(' : response without / with a preceding space.
AFTER_PAREN = {
    char: (plain, spaced)
    for chars, plain, spaced in (
        ('-', -2.4, -3.2),
        ('*', -4.2, -5.1),
        ('!', -5.1, -4.6),
        ('+', -4.2, -5.8),
        ('/', -2.7, -4.4),
        ('@#', -2.5, -4.2),
        ('$', -1.4, -2.9),
        ('&', -2.0, -3.9),
        ('|^<>;:=?~', -3.3, -4.4),
        ('_', -1.7, -2.7),
        ('%', -2.4, -3.3),
        ('.', -2.8, -4.5),
        ('`', -0.7, -2.3),
        ('�', -1.4, -2.5),
    )
    for char in chars
}


def punctuation(token):
    spaced = int(token.startswith(' '))
    s = token.lstrip(' ')
    if not s or any(c.isalnum() for c in s):
        return 0.0
    newline = '\n' in s or '\r' in s
    if all(c in '!！?？' for c in s):
        values = (-0.42, -0.59) if any(c in '?？' for c in s) else (-0.55, -0.67)
        return values[spaced]
    if s in ('…', '...', '……'):
        return (-0.60, -0.76)[spaced]

    # Parentheses: distinguish symbolic arguments from empty or nested delimiters.
    p = s.lstrip('.*')
    if p.startswith('('):
        r = p[1:]
        head = r[:1]
        if r.startswith(('[]', '()')):
            value = (-3.8, -4.1)[spaced]
        elif head in ('(', '[', '{', ')'):
            nested = r.lstrip('(')
            if head == '(' and nested[:1] in AFTER_PAREN:
                value = AFTER_PAREN[nested[0]][spaced]
            else:
                value = {'(': (-0.45, -1.13), '[': (-1.2, -2.25),
                         '{': (-1.17, -2.43), ')': (-0.44, -1.42)}[head][spaced]
        elif head in ('"', "'", '“', '\\'):
            if r[1:2] in ('%', '/', '.', '-', '#', '[', '$', '<'):
                value = -1.7 - 0.7 * spaced
            else:
                value = (-0.45 if head == '\\' else -0.02) - 0.9 * spaced
        elif head in AFTER_PAREN:
            value = AFTER_PAREN[head][spaced]
            if ')' in r or '(' in r:
                value *= 0.75
        else:
            value = -0.66 if spaced and newline else (0.0 if spaced else 0.1)
        return value * (0.5 if newline and len(r) > 1 else 1.0)

    # Square and curly delimiters have weaker versions of the same response.
    if s[0] in '[{':
        r = s[1:]
        head = r[:1]
        if r.startswith(('...', '…')):
            value = -2.3 if any(c in ']}' for c in r) else -4.6
        elif head in ('*', ':'):
            value = (-2.8, -4.3)[spaced]
        elif head in ('-', '/', '@', '#', '+', ',', '<', '^', '&'):
            value = (-2.25, -2.65)[spaced]
        elif head in ('$', '%', '|', '='):
            value = (-1.2, -1.6)[spaced]
        else:
            value = {']': (-0.83, -1.0), '}': (-0.41, -1.0),
                     '(': (-0.35, -0.6), '[': (-0.35, -0.6),
                     '\\': (0.0, -0.36)}.get(head, (0.0, 0.0))[spaced]
        return value * (0.5 if newline else 1.0)

    if newline:
        return -0.13 if s.startswith('!') else 0.0
    if '{-' in s:
        return -1.7
    if s.startswith((',...', ',…', '<!--')):
        return -1.4
    if s.startswith(('</', './', '.-')):
        return -0.65
    if s.startswith(('/*', '&#', ',-', ',@')):
        return -0.85
    if s.startswith(('/_', '/.', '/-', '/~', '/#', '/@', '=/', '=-', ':+', '<?')):
        return -1.2
    quoted_symbol = s[1:2] in ('/', '$', '#', '_', '-', '<', '+', '{', '[', '.', '@')
    if spaced and s[0] in '\"\'`' and quoted_symbol:
        return -0.9 if s[1:] else 0.0
    if len(s) == 2 and s[0] in ',:;=.' and s[1] != s[0]:
        if s[1] in '*!':
            return -1.8 if s[0] != '.' or s[1] == '!' else -0.65
        if s[1] in '-+/@#%._&<':
            return -0.6 if s[0] == '.' else -0.95
    return -0.43 if s.startswith('._') else 0.0


def step(carry, prefix, upstream):
    return None, float(punctuation(prefix.token_strings[-1]))

programs.luna:
"""Predict a negative response to a few common punctuation patterns."""
import unicodedata

READS: tuple[str, ...] = ()
_OPENERS = frozenset("([{<")


def _punctuation(ch):
    return unicodedata.category(ch)[0] in "PS"


def step(carry, prefix, upstream):
    # Ignore token-leading spaces when recognizing the visible punctuation.
    s = "".join(ch for ch in prefix.token_strings[-1] if not ch.isspace())
    if not s:
        return None, 0.0

    # Negated conditions and parenthesized minus expressions stand out most.
    if s.startswith("(!"):
        return None, -4.1
    if s.startswith("(-"):
        return None, -2.6

    # Less distinctive punctuation after an opening delimiter gets a small value.
    if len(s) > 1 and s[0] in _OPENERS and _punctuation(s[1]):
        return None, -0.35

    # Exclamation fragments and ellipses are negative; a leading question mark is milder.
    if "!" in s:
        return None, -0.58
    if s.startswith("...") or s.startswith("…"):
        return None, -0.65
    if s.startswith("?"):
        return None, -0.26

    # Other adjacent punctuation, such as operators and markup, is only a weak cue.
    for left, right in zip(s, s[1:]):
        if _punctuation(left) and _punctuation(right):
            return None, -0.04
    return None, 0.0

programs.sol:
"""Approximate the component's short-range response to 'what' phrases.

Common grammatical words distinguish negative 'what is/was' from positive
'what does/do', 'what the', and demonstratives.  Later naming, appearance,
comparison, and category phrases have separate rules.  Most responses fade
with token distance; the 'what' window lasts seven tokens.  Other wh-words
and indefinite pronouns get weaker four-token responses.  Elsewhere only
do/does/did have small baselines; document-initial 'what' can also be positive.
Document changes reset state, and sentence punctuation expires the phrase.
Low-amplitude, vocabulary-specific background responses are not modeled.
"""
import re

READS = ()
BE = {'is', 'was', 'are', 'were', 'am', "'s", '’s', 'be', 'been', 'being'}
DO = {'do', 'does', 'did', 'doing'}
MODALS = {'will', 'would', 'can', 'could', 'should', 'may', 'might', 'must'}
APPEARANCE = {'appear', 'appears', 'appeared', 'seem', 'seems', 'seemed',
              'look', 'looks', 'looked', 'feel', 'feels', 'felt'}
NAMING = {'call', 'calls', 'called', 'termed', 'named'}
OTHER_WH = {'where': 1.15, 'why': 0.9, 'how': 0.6,
            'which': 0.5, 'who': 0.5, 'when': 0.4}
INDEFINITE = {'whatever', 'anything', 'something', 'everything', 'nothing'}
IMMEDIATE_GRAMMAR = {
    'is': -2.2, 'was': -1.8, 'are': -1.15, 'were': -0.8, 'am': -1.25,
    "'s": -1.93, '’s': -1.68,
    'do': 3.2, 'does': 3.95, 'did': 3.0,
    'the': 1.84, 'a': 0.55, 'an': 0.5, 'it': 1.55,
    'this': 2.15, 'that': 2.3, 'these': 2.1, 'those': 2.7, 'each': 2.4,
    'i': -0.23, 'we': -0.11, 'you': 0.17, 'they': 0.45,
    'your': 0.84, 'their': 1.35, 'can': 0.91,
    'will': -0.41, 'would': -0.22, 'may': -0.95, 'might': -0.6,
    'about': -1.0, 'else': 0.6,
}


def phrase_response(word, previous, distance):
    if distance == 1:
        if word in IMMEDIATE_GRAMMAR:
            return IMMEDIATE_GRAMMAR[word]
        if word in APPEARANCE or word == 'be':
            return -2.1
        if word in {'makes', 'works', 'needs'}:
            return -0.8
        if word in {'kind', 'type', 'sort', 'form', 'way'}:
            return 1.0
        return 0.0
    fade = 0.67 ** (distance - 2)
    if word in DO:
        return {'do': 1.75, 'does': 2.35, 'did': 1.75, 'doing': 1.3}[word] * fade
    if word in BE:
        return (-2.4 if word == 'be' else -1.55 if word in {'been', 'being'}
                else -0.7) * fade
    if word in NAMING:
        return -3.0 * 0.76 ** (distance - 2)
    if word == 'the':
        return (2.8 if previous in DO else 1.3 if previous in MODALS
                else 0.05 if distance == 2 else 0.4) * fade
    if word in {'this', 'that', 'these', 'those', 'it'}:
        return (1.8 if previous in DO else 1.0) * fade
    if word in {'a', 'an', 'some'}:
        return (1.2 if previous in DO else -0.7) * fade
    if word in {'more', 'next', 'now'}:
        return (-2.3 if previous in BE else -0.7) * fade
    if word == 'of' and previous in {'kind', 'type', 'sort', 'form'}:
        return 1.2 * fade
    if word in {'like', 'as', 'about', 'to'} and previous in APPEARANCE:
        return -2.3 * 0.9 ** (distance - 2)
    if word in APPEARANCE | {'like', 'as', 'about', 'going', 'coming', 'not'}:
        return -1.1 * fade
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    distance, trigger, previous = (99, '', '') if reset else carry[1:]
    distance += 1
    raw = prefix.token_strings[-1]
    word = raw.strip().strip('"“”').lower()
    value = {'does': 0.16, 'did': 0.18, 'do': -0.06}.get(word, 0.0)
    if trigger == 'what' and distance <= 7:
        value = phrase_response(word, previous, distance)
        if raw.strip() in {'Is', 'Do', 'Does'}:
            value *= 0.65
    elif trigger in INDEFINITE and distance <= 4:
        value = 0.32 * phrase_response(word, previous, distance)
    elif trigger in OTHER_WH and distance <= 4 and word in DO:
        value = OTHER_WH[trigger] * 0.65 ** (distance - 1)
        if word == 'do':
            value *= 0.6
    if re.search(r'\bwhat$', raw, re.I):
        trigger, distance = 'what', 0
        if reset:
            value = 1.4 if raw == 'What' else 1.05 if raw == ' what' else 0.0
    elif word in OTHER_WH or word in INDEFINITE:
        trigger, distance = word, 0
    elif any(c in raw for c in '.!?;\n'):
        trigger, distance = '', 99
    return (doc, distance, trigger, word), float(value)

programs.haiku:
"""Layer-0 MLP unit 4668: the "what X ..." clause detector.

The unit reads the word right after "what" (also a few words later in the same clause)
and writes a signed signal that depends on what kind of word it is:

  * do-support verbs (do, does, did, doing)            -> strongly positive (~+3.6)
  * the pronouns/determiners it, the, this, that        -> positive (~+1.8)
  * linking verbs: is, are, was, be, 's, seems, appears,
    looks like, is called, makes, about                 -> strongly negative (~-2)

So "what does ..." pushes positive, "what is ..." pushes negative. The strength is
divided by d, the number of tokens since "what" (d = 1 is the very next word), so it
fades quickly. Other wh-words (which, who, how, where, why) do not trigger it, and
nothing fires with no "what" earlier in the same document.

The carry is d for the current token (None when no "what" is in scope), reset at each
new document.
"""

READS = ()

WHAT = {"what", "What"}
DO = {"do", "does", "did", "doing"}
THE = {"the", "it", "this", "that"}
LINKING = {"is", "are", "was", "were", "be", "been", "am", "Is", "Are", "'s", "’s",
           "seems", "seemed", "appears", "like", "about", "makes", "called", "percent"}


def value(word):
    if word in DO:
        return 3.6
    if word in THE:
        return 1.8
    if word in LINKING:
        return -2.0
    return 0.0


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        carry = None
    if word in WHAT:
        return 0, 0.0
    if carry is None:
        return None, 0.0
    d = carry + 1
    return d, value(word) / d

