    "is": -2.2, "was": -1.8, "are": -1.2, "been": -1.6,
    "'s": -1.7, "’s": -1.7, "not": -0.8, "makes": -0.9,
    "appear": -1.4, "me": -0.5,
    "be": -1.4, "about": -0.9, "as": -1.0, "needs": -0.6,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    words = [
        prefix.token_strings[i].strip().lower()
        for i in range(max(0, len(prefix) - 7), len(prefix))
        if prefix.document_ids[i] == doc
    ]
    current = words[-1]
    value = POSITIVE.get(current, NEGATIVE.get(current, 0.0))
    if not value:
        return None, 0.0

    distance = next(
        (
            i
            for i, word in enumerate(reversed(words[:-1]), 1)
            if word in WHAT_WORDS
        ),
        None,
    )
    if distance is None:
        return None, 0.0
    return None, value / (1.0 + 0.5 * (distance - 1))

programs.sol:
"""Lexical triggers for supersession/excess and for vivid colour.

The largest negative is an override annotation (Java or Dart); override in
ordinary prose or an identifier is weaker.  Related excess words and method
metadata give smaller negatives.  The positive side recognizes Chinese 彩
(colour/lottery), related colour words, and vivid English words.  It also
includes the Chinese characters 采 and 啪.  A short-lived state handles the
following method signature and resets at document boundaries.  Most tokens
are assigned a near-zero value; this omits many weaker, unrelated triggers.
"""
READS = ()

METHOD_METADATA = {
    'abstractmethod', 'staticmethod', 'classmethod', 'NotImplemented',
    'NotImplementedException', 'RequestParam', 'XmlElement',
}
INJECTION_METADATA = {
    'Autowired', 'RequestMapping', 'GetMapping', 'PostMapping', 'NonNull',
}
EXCESS_OR_SUPERSESSION = {
    'overcome', 'overcoming', 'overload', 'overrun', 'outweigh',
}
VIVID_WORDS = {'vibrant', 'vivid', 'scarlet'}


def lexical_value(token):
    raw = token.strip()
    word = raw.lstrip('@._')
    lower = word.lower()
    if lower == 'override':
        return -4.5
    if lower in {'overrides', 'overridden', 'overriding'}:
        return -2.9
    if lower == 'inheritdoc':
        return -3.5
    if lower.startswith('overwhelm'):
        return -2.8 if lower == 'overwhelming' else -1.8
    if lower.startswith('overpower'):
        return -1.9
    if lower in EXCESS_OR_SUPERSESSION:
        return -1.05
    if lower.startswith(('overflow', 'overshadow', 'overst')):
        return -0.7
    if lower.startswith('overwrit'):
        return -0.55
    if word in METHOD_METADATA:
        return -1.6
    if word in INJECTION_METADATA:
        return -0.7
    if word == 'GeneratedValue':
        return -2.2
    if word == 'subpackage':
        return -1.0
    if word == 'Column' and raw.startswith(('@', '.')):
        return -0.4
    if word == '彩':
        return 4.7
    if word == '博彩':
        return 0.9
    if '彩' in word:
        return 2.1 if len(word) == 2 else 1.4
    if word in {'采', '风采', '啪'}:
        return 0.9
    if lower in {'colorful', 'colourful'}:
        return 1.2
    if lower in VIVID_WORDS:
        return 0.75
    if word in {'Color', 'Beauty'}:
        return 0.3
    if word == 'void' and token[:1].isspace():
        return -0.2
    if lower in {'virtual', 'abstract'}:
        return -0.3
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    age, previous = (99, '') if carry is None or carry[0] != doc else (
        carry[1] + 1, carry[2]
    )
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('@._')
    lower = word.lower()
    value = lexical_value(token)
    if lower == 'override':
        if token.strip().startswith('@') or previous.rstrip().endswith('@'):
            value = -6.85 if token.strip().startswith('@') else -6.2
            age = 0
        elif previous.strip() in {'public', 'protected', 'internal'}:
            value = -6.1
    if word == 'void' and previous.strip().lower() == 'override':
        value = -1.9
    elif word == 'the' and previous.strip().lower() in {
        'override', 'overrides', 'overridden', 'overriding',
    }:
        value = -0.5
    elif age <= 4:
        if word == 'public':
            value = -0.5 if '\t' in token else -0.9
        elif word == 'protected':
            value = -0.3
        elif word == 'void':
            value = -1.05
        elif age == 1 and '\n' in token and not word:
            value = -0.5
    return (doc, age, token), float(value)

programs.luna:
"""Recognize a few annotation labels in code; ordinary text predicts zero."""

READS = ()

ANNOTATION_ACTIVATIONS = {
    "Override": -6.3,
    "@Override": -6.5,
    "GeneratedValue": -2.2,
    "GetMapping": -1.0,
    "abstractmethod": -1.4,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    return None, float(ANNOTATION_ACTIVATIONS.get(token, 0.0))
